class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        take = True
        rows = len(grid)
        cols = len(grid[0]) if rows else 0

        for r in range(rows):
            if r % 2 == 0:
                col_range = range(cols)
            else:
                col_range = range(cols - 1, -1, -1)

            for c in col_range:
                if take:
                    result.append(grid[r][c])
                take = not take

        return result

