class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)

        # Group indices by value (indices are appended in sorted order)
        groups = {}
        for i, v in enumerate(nums):
            groups.setdefault(v, []).append(i)

        ans = [-1] * n

        for idxs in groups.values():
            m = len(idxs)
            if m < 2:
                continue
            for k in range(m):
                cur = idxs[k]
                prev = idxs[(k - 1) % m]
                nxt = idxs[(k + 1) % m]

                d_prev = abs(cur - prev)
                d_prev = min(d_prev, n - d_prev)
                d_next = abs(cur - nxt)
                d_next = min(d_next, n - d_next)

                ans[cur] = min(d_prev, d_next)

        return [ans[q] for q in queries]

class Solution:
    def maxWeight(self, pizzas: List[int]) -> int:
        from math import ceil
        n = len(pizzas)
        m = n // 4  # number of days
        o = (m + 1) // 2  # odd days
        a = sorted(pizzas)[2 * m:]  # largest 2m pizzas (the two largest of each group)
        # Optimal: odd days get the o largest elements; even days get elements
        # at positions o..m-1; the rest are "wasted".
        return sum(a[2 * m - o:]) + sum(a[o:m])

