    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)

        # cyclic distance between two letters
        D = [[0] * 26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                d = a - b
                if d < 0:
                    d = -d
                if d > 13:
                    d = 26 - d
                D[a][b] = d

        # min cost to make two letters equal (target letter chosen optimally)
        C = [[0] * 26 for _ in range(26)]
        for a in range(26):
            for b in range(26):
                best = 52
                for x in range(26):
                    v = D[a][x] + D[b][x]
                    if v < best:
                        best = v
                C[a][b] = best

        v = [ord(ch) - 97 for ch in s]

        # dp[i][j][m] = longest palindromic subsequence in s[i..j] using <= m operations
        dp = [[None] * n for _ in range(n)]
        one = [1] * (k + 1)
        for i in range(n):
            dp[i][i] = one

        for length in range(2, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                c = C[v[i]][v[j]]
                prev_i = dp[i + 1][j]
                prev_j = dp[i][j - 1]
                inner = dp[i + 1][j - 1] if i + 1 <= j - 1 else None
                arr = [0] * (k + 1)
                if inner is None:
                    if c <= k:
                        for m in range(c, k + 1):
                            best = prev_i[m] if prev_i[m] >= prev_j[m] else prev_j[m]
                            if best < 2:
                                best = 2
                            arr[m] = best
                        for m in range(c):
                            arr[m] = prev_i[m] if prev_i[m] >= prev_j[m] else prev_j[m]
                    else:
                        for m in range(k + 1):
                            arr[m] = prev_i[m] if prev_i[m] >= prev_j[m] else prev_j[m]
                else:
                    for m in range(k + 1):
                        best = prev_i[m] if prev_i[m] >= prev_j[m] else prev_j[m]
                        if c <= m:
                            val = 2 + inner[m - c]
                            if val > best:
                                best = val
                        arr[m] = best
                dp[i][j] = arr

        return dp[0][n - 1][k]

