    # Odd Manacher: d[i] = max k such that s[i-k+1..i+k-1] is palindrome
    d = [0] * n
    l = 0
    r = -1
    for i in range(n):
        k = 1 if i > r else min(d[l + r - i], r - i + 1)
        while i - k >= 0 and i + k < n and s[i - k] == s[i + k]:
            k += 1
        d[i] = k
        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    # Even Manacher: d2[i] = max k such that s[i-k+1..i+k] is palindrome (center between i and i+1)
    d2 = [0] * n
    l = 0
    r = -1
    for i in range(n):
        if i > r:
            k = 0
        else:
            k = min(d2[l + r - i + 1], r - i + 1)
        while i + k + 1 < n and i - k >= 0 and s[i + k + 1] == s[i - k]:
            k += 1
        d2[i] = k
        if i + k - 1 > r:
            l = i - k + 1
            r = i + k - 1

    # Longest palindromic suffix: palindrome ending at n-1
    best = 0
    # odd palindrome ending at n-1: center i, length 2k-1, ends at i+k-1 == n-1
    for i in range(n):
        if i + d[i] - 1 == n - 1:
            length = 2 * d[i] - 1
            if length > best:
                best = length
    # even palindrome ending at n-1: center i, length 2k, ends at i+k == n-1
    for i in range(n):
        if i + d2[i] == n - 1:
            length = 2 * d2[i]
            if length > best:
                best = length

    m = n - best
    answer = s + s[:m][::-1]
