class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        total_odds = (n + 1) // 2
        total_evens = n // 2

        # Total number of alternating permutations
        if n % 2 == 0:
            # Two parity patterns: O E O E ... and E O E O ...
            total = 2 * fact[total_odds] * fact[total_evens]
        else:
            # Only one pattern: O E O E ... O
            total = fact[total_odds] * fact[total_evens]

        if k > total:
            return []

        used = [False] * (n + 1)
        used_odds = 0
        used_evens = 0
        result = []

        for i in range(n):
            chosen = -1
            for v in range(1, n + 1):
                if used[v]:
                    continue
                # Parity must alternate with previous element
                if i > 0 and (v % 2) == (result[-1] % 2):
                    continue

                # Remaining counts after placing v
                ro = total_odds - used_odds - (1 if v % 2 == 1 else 0)
                re = total_evens - used_evens - (1 if v % 2 == 0 else 0)

                # Required number of odd-parity positions in the remaining slots
                m = n - i - 1
                if v % 2 == 1:
                    req_odds = m // 2        # odd numbers sit at even offsets
                else:
                    req_odds = (m + 1) // 2  # odd numbers sit at odd offsets
                if ro != req_odds:
                    continue

                cnt = fact[ro] * fact[re]
                if k <= cnt:
                    chosen = v
                    break
                k -= cnt

            if chosen == -1:
                return []

            result.append(chosen)
            used[chosen] = True
            if chosen % 2 == 1:
                used_odds += 1
            else:
                used_evens += 1

        return result

