class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)
        if k > n:
            return 0

        def ok(d: int) -> bool:
            # d == 0: trivially feasible
            if d <= 0:
                return True
            # Opposite-side pairs are always compatible when d <= side.
            # Handle the general case with an exact branch-and-bound.
            # Sort by perimeter order to get good pruning.
            # Perimeter order starting at bottom-left corner, going clockwise.
            def perim(p):
                x, y = p
                if y == 0:
                    return x  # bottom edge left->right
                if x == side:
                    return side + y  # right edge bottom->top
                if y == side:
                    return 2 * side + (side - x)  # top edge right->left
                # left edge top->bottom
                return 3 * side + (side - y)

            order = sorted(range(n), key=lambda i: perim(points[i]))
            pts = [points[i] for i in order]

            def dist(a, b):
                return abs(a[0] - b[0]) + abs(a[1] - b[1])

            # Precompute compatibility on the fly.
            # Use DFS with pruning.
            selected = []
            # Count how many points are still compatible with all selected (for pruning).
            # This is computed incrementally to avoid O(n*k) per node too often.
            def compatible_all(p):
                for q in selected:
                    if dist(p, q) < d:
                        return False
                return True

            def dfs(pos: int, need: int) -> bool:
                if need == 0:
                    return True
                # Remaining count lower bound
                remaining = n - pos
                if remaining < need:
                    return False
                # If we can take all remaining compatible points? Not enough; need need.
                # Simple forward-checking: count candidates that are compatible with all selected.
                # To save time, do a bounded check.
                # Try candidates in perimeter order.
                for i in range(pos, n):
                    p = pts[i]
                    if not compatible_all(p):
                        continue
                    selected.append(p)
                    if dfs(i + 1, need - 1):
                        return True
                    selected.pop()
                    # Optional strong pruning: if we reached k, done (handled by need==0)
                return False

            # For very small d, greedy/complete is easy; DFS should find quickly.
            return dfs(0, k)

        lo, hi = 0, side
        # Feasible(0) is True (k points distinct, distance>=0)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if ok(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo
